begin;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,encrypted_password) values
('ff000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','student-recovery-admin1@fixture.invalid',now(),'fictional'),
('ff000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','student-recovery-admin2@fixture.invalid',now(),'fictional'),
('ff000000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','dxm-7k3m9q2rw5t2@members.dexam.invalid',now(),'fictional');
insert into public.people(id,display_name,member_id) values
('ff100000-0000-4000-8000-000000000001','Recovery Admin One',null),('ff100000-0000-4000-8000-000000000002','Recovery Admin Two',null),('ff100000-0000-4000-8000-000000000003','Recovery Student','DXM-7K3M9Q2RW5T2');
insert into public.auth_identities(person_id,auth_user_id,kind) values
('ff100000-0000-4000-8000-000000000001','ff000000-0000-4000-8000-000000000001','employee_email'),('ff100000-0000-4000-8000-000000000002','ff000000-0000-4000-8000-000000000002','employee_email'),('ff100000-0000-4000-8000-000000000003','ff000000-0000-4000-8000-000000000003','member_id');
insert into public.memberships(person_id,kind,status) values('ff100000-0000-4000-8000-000000000001','employee','active'),('ff100000-0000-4000-8000-000000000002','employee','active'),('ff100000-0000-4000-8000-000000000003','student','active');
insert into public.role_assignments(person_id,role_key,grant_reason) values('ff100000-0000-4000-8000-000000000001','elevated_admin','Fictional recovery proposer'),('ff100000-0000-4000-8000-000000000002','elevated_admin','Fictional recovery approver');
insert into public.offerings(id,code,title,status) values('ff600000-0000-4000-8000-000000000001','RECOVERY_FIXTURE','Recovery Fixture','active');
insert into public.enrollments(person_id,offering_id,status,source_type) values('ff100000-0000-4000-8000-000000000003','ff600000-0000-4000-8000-000000000001','completed','manual');
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values('ff200000-0000-4000-8000-000000000001','ff000000-0000-4000-8000-000000000001','totp','verified',now(),now()),('ff200000-0000-4000-8000-000000000002','ff000000-0000-4000-8000-000000000002','totp','verified',now(),now());
insert into auth.sessions(id,user_id,factor_id,aal,created_at,updated_at) values('ff300000-0000-4000-8000-000000000001','ff000000-0000-4000-8000-000000000001','ff200000-0000-4000-8000-000000000001','aal2',now(),now()),('ff300000-0000-4000-8000-000000000002','ff000000-0000-4000-8000-000000000002','ff200000-0000-4000-8000-000000000002','aal2',now(),now());
insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values('ff400000-0000-4000-8000-000000000001','ff300000-0000-4000-8000-000000000001','totp',now(),now()),('ff400000-0000-4000-8000-000000000002','ff300000-0000-4000-8000-000000000002','totp',now(),now());
set local role anon;
select throws_ok('select public.list_student_recovery_requests()','42501',null,'anonymous recovery queue denied');
select throws_ok($$select public.find_student_recovery_target('DXM-7K3M9Q2RW5T2')$$,'42501',null,'anonymous recovery identity discovery denied');
reset role;
set local role authenticated;
set local request.jwt.claims='{"sub":"ff000000-0000-4000-8000-000000000001","session_id":"ff300000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}';
select is(public.current_person_can_assist_student_recovery(),false,'password-only Elevated Admin denied');
select throws_ok($$select public.propose_student_recovery('ff100000-0000-4000-8000-000000000003','forgotten_password',true,true)$$,'42501',null,'password-only proposal denied');
set local request.jwt.claims='{"sub":"ff000000-0000-4000-8000-000000000001","session_id":"ff300000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}';
select is(public.current_person_can_assist_student_recovery(),true,'recent Elevated Admin can propose');
select is((select count(*)::integer from public.find_student_recovery_target('DXM-7K3M9Q2RW5T2')),1,'claimed student with established enrolment found by exact Member ID');
select is((select count(*)::integer from public.find_student_recovery_target('Recovery')),0,'names cannot act as account recovery identifiers');
select throws_ok('select * from public.student_recovery_requests','42501',null,'browser cannot inspect raw recovery ledger');
select throws_ok($$select public.propose_student_recovery('ff100000-0000-4000-8000-000000000003','forgotten_password',false,true)$$,'22023',null,'identity evidence acknowledgment required');
select throws_ok($$select public.propose_student_recovery('ff100000-0000-4000-8000-000000000003','forgotten_password',true,false)$$,'22023',null,'enrolment evidence acknowledgment required');
select throws_ok($$select public.propose_student_recovery('ff100000-0000-4000-8000-000000000001','forgotten_password',true,true)$$,'42501',null,'administrator cannot propose own canonical-person recovery');
select set_config('test.student_recovery',(public.propose_student_recovery('ff100000-0000-4000-8000-000000000003','forgotten_password',true,true))::text,true);
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'42501',null,'proposer cannot approve own reset');
select is((select status from public.list_student_recovery_requests() where id=current_setting('test.student_recovery')::uuid),'pending','one actor cannot issue a recovery pack');
set local request.jwt.claims='{"sub":"ff000000-0000-4000-8000-000000000002","session_id":"ff300000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}';
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,false,true)$$,'22023',null,'independent identity review required');
reset role;
update public.role_assignments set revoked_at=now() where person_id='ff100000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'42501',null,'revoked proposer cannot authorize approval');
reset role;
update public.role_assignments set revoked_at=null where person_id='ff100000-0000-4000-8000-000000000001';
update public.memberships set status='suspended' where person_id='ff100000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'42501',null,'suspended approver denied');
reset role;
update public.memberships set status='active' where person_id='ff100000-0000-4000-8000-000000000002';
update public.role_assignments set revoked_at=now() where person_id='ff100000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'42501',null,'revoked approver denied');
reset role;
update public.role_assignments set revoked_at=null where person_id='ff100000-0000-4000-8000-000000000002';
update public.memberships set status='suspended' where person_id='ff100000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'42501',null,'student suspension cannot be restored by recovery');
reset role;
update public.memberships set status='active' where person_id='ff100000-0000-4000-8000-000000000003';
update public.people set status='archived' where id='ff100000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'42501',null,'archived student denied');
reset role;
update public.people set status='active' where id='ff100000-0000-4000-8000-000000000003';
update auth.users set email='other@fixture.invalid' where id='ff000000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'42501',null,'changed synthetic Auth ownership denied');
reset role;
update auth.users set email='dxm-7k3m9q2rw5t2@members.dexam.invalid',banned_until=now()+interval '1 hour' where id='ff000000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'42501',null,'provider-banned account is not restored');
reset role;
update auth.users set banned_until=null where id='ff000000-0000-4000-8000-000000000003';
update public.enrollments set status='cancelled' where person_id='ff100000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'42501',null,'no established admitted enrolment evidence denied');
reset role;
update public.enrollments set status='completed' where person_id='ff100000-0000-4000-8000-000000000003';
select throws_ok($$update public.student_recovery_requests set approver_person_id=target_person_id where id=current_setting('test.student_recovery')::uuid$$,'23514',null,'target cannot be recorded as own approver');
set local role authenticated;
select lives_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'different recent administrator approves exact request');
select throws_ok($$select public.decide_student_recovery(current_setting('test.student_recovery')::uuid,true,true,true)$$,'55000',null,'approval replay denied');
select is((select status from public.list_student_recovery_requests() where id=current_setting('test.student_recovery')::uuid),'approved','independent approval recorded');
reset role;
select is((select count(*)::integer from public.account_action_tokens where person_id='ff100000-0000-4000-8000-000000000003'),0,'approval alone does not create a credential or change password');
select is((select member_id from public.people where id='ff100000-0000-4000-8000-000000000003'),'DXM-7K3M9Q2RW5T2','Member ID unchanged');
select is((select status::text from public.enrollments where person_id='ff100000-0000-4000-8000-000000000003'),'completed','recovery never restores ended enrolment');
select is((select count(*)::integer from public.security_audit_events where subject_person_id='ff100000-0000-4000-8000-000000000003' and event_type in ('student_recovery_proposed','student_recovery_decided')),2,'minimized proposal/independent decision audit');
set local role authenticated;
select lives_ok($$select public.cancel_student_recovery(current_setting('test.student_recovery')::uuid)$$,'authorized cancellation does not require granting access');
select throws_ok($$select public.cancel_student_recovery(current_setting('test.student_recovery')::uuid)$$,'55000',null,'cancellation replay denied');
reset role;
update public.role_assignments set role_key='teacher' where person_id='ff100000-0000-4000-8000-000000000002';
set local role authenticated;
select is(public.current_person_can_assist_student_recovery(),false,'Teacher cannot assist password reset');
reset role;
update public.role_assignments set role_key='sales' where person_id='ff100000-0000-4000-8000-000000000002';
set local role authenticated;
select is(public.current_person_can_assist_student_recovery(),false,'Sales cannot assist password reset');
reset role;
update public.role_assignments set role_key='ordinary_admin' where person_id='ff100000-0000-4000-8000-000000000002';
set local role authenticated;
select is(public.current_person_can_assist_student_recovery(),false,'Enrolment Operator broad role cannot reset activated accounts');
reset role;
update public.role_assignments set role_key='elevated_admin' where person_id='ff100000-0000-4000-8000-000000000002';
update auth.mfa_amr_claims set updated_at=now()-interval '20 minutes' where id='ff400000-0000-4000-8000-000000000002';
set local role authenticated;
select is(public.current_person_can_assist_student_recovery(),false,'stale administrator verification denied');
select * from finish();
rollback;
